/**
 * Regenerate the admin app's tab registry from what is actually installed.
 *
 * The app used to import all 24 panels and list all 24 tabs, which meant a
 * minimal install still compiled and shipped every feature. Now App.tsx
 * imports one generated file, and this writes it from the panels that are
 * present on disk. A panel that was never copied in is never imported, so it
 * costs nothing - not in the bundle, not in the tab bar.
 *
 * Reads:  install/tabs.json  (label, hint, icon, component and props per tab)
 * Checks: <admin>/src/<from>.tsx exists for that tab
 * Writes: <admin>/src/modules.generated.tsx
 *
 * Environment: ADMIN_DIR, set by install/install.env.
 */
const fs = require('fs')
const path = require('path')

const INSTALL = path.resolve(__dirname, '..')
const ADMIN = process.env.ADMIN_DIR
if (!ADMIN) {
  console.error('ADMIN_DIR is not set')
  process.exit(2)
}

const tabs = JSON.parse(fs.readFileSync(path.join(INSTALL, 'tabs.json'), 'utf8'))

/** Is this tab's panel present? A folder import resolves to its index file. */
function present(tab) {
  if (!tab.from) return false
  const base = path.join(ADMIN, 'src', tab.from.replace(/^\.\//, ''))
  return ['.tsx', '.ts', '/index.tsx', '/index.ts'].some((ext) => fs.existsSync(base + ext))
}

const live = tabs.filter(present)
const icons = [...new Set(live.map((t) => t.icon))].sort()
const components = [...new Set(live.map((t) => `${t.component}|${t.from}`))].sort()

const lines = []
lines.push('// GENERATED by install/lib/write-registry.js - do not edit.')
lines.push('//')
lines.push('// One entry per installed tab. Installing a module copies its panel in and')
lines.push('// reruns the generator; uninstalling removes the panel and reruns it. The')
lines.push('// app imports nothing else, so the bundle matches the install.')
lines.push('//')
lines.push(`// ${live.length} of ${tabs.length} tabs installed.`)
lines.push('')
lines.push("import type { ComponentType } from 'react'")
lines.push("import type { LucideIcon } from 'lucide-react'")
if (icons.length) lines.push(`import { ${icons.join(', ')} } from 'lucide-react'`)
for (const c of components) {
  const [name, from] = c.split('|')
  lines.push(`import { ${name} } from '${from}'`)
}
lines.push('')
lines.push('export type TabEntry = {')
lines.push('  id: string')
lines.push('  label: string')
lines.push('  hint: string')
lines.push('  Icon: LucideIcon')
lines.push('  /** The panel. Most take the movie; one or two take nothing. */')
lines.push('  Component: ComponentType<any>')
lines.push('  /** Fixed props, for panels that serve more than one tab. */')
lines.push('  props: Record<string, string>')
lines.push('  takesMovie: boolean')
lines.push('  module: string')
lines.push('  /** Where it sits in the menu: a step of making the film, or the workshop. */')
lines.push("  group: 'story' | 'cast' | 'sets' | 'shots' | 'finish' | 'workshop'")
lines.push('}')
lines.push('')
lines.push('export const TAB_ENTRIES: TabEntry[] = [')
for (const t of live) {
  const props = JSON.stringify(t.props || {})
  lines.push(`  { id: '${t.id}', label: ${JSON.stringify(t.label)}, hint: ${JSON.stringify(t.hint)},`)
  lines.push(`    Icon: ${t.icon}, Component: ${t.component}, props: ${props}, takesMovie: ${!!t.takesMovie}, module: '${t.module}', group: '${t.group || 'workshop'}' },`)
}
lines.push(']')
lines.push('')
lines.push('/** Every module this build has a tab for. */')
lines.push(`export const INSTALLED_MODULES: string[] = ${JSON.stringify([...new Set(live.map((t) => t.module))].sort())}`)
lines.push('')

const out = path.join(ADMIN, 'src', 'modules.generated.tsx')
fs.writeFileSync(out, lines.join('\n'), 'utf8')
console.log(`registry: ${live.length} tab(s) -> ${path.relative(process.cwd(), out)}`)
for (const t of tabs.filter((t) => !present(t))) {
  console.log(`  not installed: ${t.id} (${t.module})`)
}
